import { createContext, ReactNode, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import he from './he';
import es from './es';
import fr from './fr';

/**
 * Lightweight i18n. Keys are the English UI strings, so English needs no dictionary and any
 * missing translation falls back to English. `{name}` placeholders are interpolated.
 * Scientific content generated by the backend (parameter descriptions, explanations, methods)
 * stays in English so that units, citations and terminology remain exact.
 */
export type Lang = 'en' | 'he' | 'es' | 'fr';
export const LANGS: { code: Lang; label: string; dir: 'ltr' | 'rtl' }[] = [
  { code: 'en', label: 'English', dir: 'ltr' },
  { code: 'he', label: 'עברית', dir: 'rtl' },
  { code: 'es', label: 'Español', dir: 'ltr' },
  { code: 'fr', label: 'Français', dir: 'ltr' },
];
const DICTS: Record<Lang, Record<string, string>> = { en: {}, he, es, fr };
const KEY = 'terranova.lang';

type T = (s: string, vars?: Record<string, string | number>) => string;
const Ctx = createContext<{ lang: Lang; setLang: (l: Lang) => void; t: T }>({ lang: 'en', setLang: () => {}, t: (s) => s });

function initial(): Lang {
  try {
    const s = localStorage.getItem(KEY) as Lang | null;
    if (s && DICTS[s]) return s;
  } catch { /* storage unavailable */ }
  const n = (navigator.language || 'en').slice(0, 2) as Lang;
  return DICTS[n] ? n : 'en';
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initial);
  const setLang = useCallback((l: Lang) => {
    setLangState(l);
    try { localStorage.setItem(KEY, l); } catch { /* ignore */ }
  }, []);
  useEffect(() => {
    const d = LANGS.find((x) => x.code === lang)!;
    document.documentElement.lang = lang;
    document.documentElement.dir = d.dir;
  }, [lang]);
  const t = useCallback<T>((s, vars) => {
    let out = DICTS[lang][s] ?? s;
    if (vars) for (const [k, v] of Object.entries(vars)) out = out.split(`{${k}}`).join(String(v));
    return out;
  }, [lang]);
  const value = useMemo(() => ({ lang, setLang, t }), [lang, setLang, t]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export const useI18n = () => useContext(Ctx);
export const useT = () => useContext(Ctx).t;
